import "./App.css";
import TodoList from "./components/TodoList";

function App() {
  return (
    <div
      className="App"
      style={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        height: "100vh",
        backgroundColor: "#962929",
        direction: "rtl",
      }}
    >
      <TodoList />
    </div>
  );
}

export default App;
